/* @lc app=leetcode id=3901 lang=kotlin */ class Solution { fun fp(spf: IntArray, x: Int): List<Int> = generateSequence(x) { y -> (y / spf[y]).takeIf { it > 1 } }.takeWhile { it > 1 }.map { spf[it] }.distinct().toList() fun ct(cnt: IntArray, sm: LongArray, freq: IntArray, bad: HashMap<Int, Int>, n: Int, q: Int, d: Int) = (if (cnt[q] > 0) freq.set(cnt[q], freq[cnt[q]] + d) else Unit).let { if (cnt[q] == n - 1) (n.toLong() * (n - 1) / 2 - sm[q]).toInt().let { idx -> bad.merge(idx, d) { a, b -> a + b }.let { if (it == 0) bad.remove(idx) } } } fun step(spf: IntArray, a: IntArray, p: Int, cnt: IntArray, sm: LongArray, freq: IntArray, bad: HashMap<Int, Int>, mm: IntArray, n: Int, idx: Int, v: Int): Boolean = a[idx].let { old -> (if (old % p == 0) fp(spf, old / p) else listOf()).let { po -> (if (v % p == 0) fp(spf, v / p) else listOf()).let { pn -> (po + pn).distinct().let { aff -> aff.forEach { ct(cnt, sm, freq, bad, n, it, -1) }.let { po.forEach { q -> cnt.set(q, cnt[q] - 1).also { sm[q] -= idx.toLong() } } }.let { pn.forEach { q -> cnt.set(q, cnt[q] + 1).also { sm[q] += idx.toLong() } } }.let { (if (old % p == 0) mm.set(0, mm[0] - 1) else Unit).let { (if (v % p == 0) mm.set(0, mm[0] + 1) else Unit).let { a.set(idx, v).let { aff.forEach { ct(cnt, sm, freq, bad, n, it, 1) }.let { mm[0] > 0 && (if (mm[0] < n) freq[mm[0]] == 0 else freq[n] == 0 && bad.size < n) } } } } } } } } } fun countGoodSubseq(nums: IntArray, p: Int, queries: Array<IntArray>): Int = nums.size.let { n -> IntArray(50001) { it }.also { s -> (2..223).forEach { i -> if (s[i] == i) (i * i..50000 step i).forEach { j -> if (s[j] == j) s[j] = i } } }.let { spf -> nums.copyOf().let { a -> IntArray(50001).let { cnt -> LongArray(50001).let { sm -> IntArray(n + 2).let { freq -> HashMap<Int, Int>().let { bad -> IntArray(1).let { mm -> (0 until n).filter { a[it] % p == 0 }.forEach { i -> fp(spf, a[i] / p).forEach { q -> cnt.set(q, cnt[q] + 1).also { sm[q] += i.toLong() } }.let { mm[0]++ } }.let { (2..50000).filter { cnt[it] > 0 }.forEach { q -> ct(cnt, sm, freq, bad, n, q, 1) } }.let { queries.count { (idx, v) -> step(spf, a, p, cnt, sm, freq, bad, mm, n, idx, v) } } } } } } } } } } }